?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JUN | Chat de demostración</title><link rel="stylesheet" href="style.css"></head><body><main class="app"><aside><header><span class="avatar">J</span><b>Chats</b><span>⋮</span></header><div class="search">⌕ Buscar un chat</div><div class="contact"><span class="avatar">✚</span><div><b>JUN · Clínica</b><small>Asistente virtual</small></div><small>Ahora</small></div><p class="note">Simulación web · No es WhatsApp oficial. Usa datos ficticios.</p></aside><section><header><span class="avatar">✚</span><div><b>JUN · Clínica</b><small>en línea · asistente virtual</small></div><span class="right">⌕　⋮</span></header><div id="messages" aria-live="polite"><div class="day">HOY</div></div><div class="quick"><button data-msg="Crear cuenta">Crear cuenta</button><button data-msg="Servicios">Servicios</button><button data-msg="Iniciar trámite">Iniciar trámite</button><button data-msg="Recuperar trámite">Recuperar trámite</button><button data-msg="Consultar expediente">Mi expediente</button><button data-msg="Menú">Menú</button></div><form id="form"><span>☺</span><input id="msg" placeholder="Escribe un mensaje" maxlength="300" autocomplete="off" required><button id="send" aria-label="Enviar">➤</button></form></section></main><script>const token=<?=json_encode($_SESSION['chat_csrf'])?>;const messages=document.querySelector('#messages'),input=document.querySelector('#msg'),send=document.querySelector('#send');let busy=false;function bubble(text,own=false){let el=document.createElement('div');el.className='bubble '+(own?'own':'bot');let body=document.createElement('div');body.textContent=text;el.append(body);let time=document.createElement('small');time.textContent=new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})+(own?' ✓✓':'');el.append(time);messages.append(el);messages.scrollTop=messages.scrollHeight;}bubble('¡Hola! Soy el asistente virtual de JUN. 👋\n¿Ya tienes una cuenta en JUN? Responde sí o no. Si prefieres consultar servicios, escribe menú.');async function talk(text){if(busy||!text.trim())return;busy=true;send.disabled=true;bubble(text,true);const typing=document.createElement('div');typing.className='bubble bot';typing.textContent='Escribiendo…';messages.append(typing);messages.scrollTop=messages.scrollHeight;input.value='';try{let r=await fetch('bot.php',{method:'POST',headers:{'X-Chat-Token':token},body:new URLSearchParams({mensaje:text})});let d=await r.json();await new Promise(resolve=>setTimeout(resolve,450));typing.remove();bubble(d.mensaje);}catch(e){typing.remove();bubble('No hay conexión con el servidor.');}finally{busy=false;send.disabled=false;input.focus();}}document.querySelector('#form').onsubmit=e=>{e.preventDefault();talk(input.value);};document.querySelectorAll('[data-msg]').forEach(b=>b.onclick=()=>talk(b.dataset.msg));</script></body></html>
